    for c, color in enumerate(row):
        if color == 2:
            # 2 grows upward according to the 1-run to its right, including itself.
            run = 0
            x = c + 1
            while x < len(row) and row[x] == 1:
                run += 1
                x += 1
            height = run + 1
        elif color == 8:
            # 8 grows upward according to the 1-run immediately to its left.
            run = 0
            x = c - 1
            while x >= 0 and row[x] == 1:
                run += 1
                x -= 1
            height = run
        else:
            continue
        for d in range(1, min(height, r0) + 1):
            out[r0 - d][c] = color if d == height else 1
    return out
